def test_repo_root_command_substitutions_are_not_quoted_for_xonsh():
    abbreviations = registry()

    for trigger, command in (
        ("cdr", "cd"),
        ("orr", "open"),
        ("cr", "code"),
        ("cir", "code-insiders"),
        ("csr", "cursor"),
    ):
        result, _ = abbreviations.expand(context(trigger))
        assert result.text == f"{command} $(_repo_root)"

